insert into public.teams (id, name, short_name, abbreviation, city, province, primary_color, accent_color, description, captain, head_coach, previous_finish, image_url, source_label, source_url, last_verified) values ('biratnagar-kings', 'Biratnagar Kings', 'Biratnagar', 'BK', 'Biratnagar', 'Koshi', '#1b2a6b', '#f5c542', 'The Kings carry the colours of eastern Nepal into Season 3. Sandeep Lamichhane leads a squad built around wrist-spin mastery, power hitting with Andre Russell and Charith Asalanka, and a fierce overseas core.', 'Sandeep Lamichhane', 'Dhammika Prasad', '3rd (2025)', null, '2026 NPL squads - Wikipedia (cites auction/retention reports)', 'https://en.wikipedia.org/wiki/2026_Nepal_Premier_League', '2026-10-22') on conflict (id) do nothing;
insert into public.teams (id, name, short_name, abbreviation, city, province, primary_color, accent_color, description, captain, head_coach, previous_finish, image_url, source_label, source_url, last_verified) values ('chitwan-rhinos', 'Chitwan Rhinos', 'Chitwan', 'CR', 'Bharatpur', 'Bagmati', '#f28c28', '#12263a', 'Based in Bharatpur, the Rhinos are an explosive side powered by Kushal Malla, international talisman Sikandar Raza, England veteran Ravi Bopara, and a dynamic mix of Nepali domestic talent.', 'Kushal Malla', 'Sohail Tanvir', '7th (2025)', null, '2026 NPL squads - Wikipedia (cites auction/retention reports)', 'https://en.wikipedia.org/wiki/2026_Nepal_Premier_League', '2026-10-22') on conflict (id) do nothing;
insert into public.teams (id, name, short_name, abbreviation, city, province, primary_color, accent_color, description, captain, head_coach, previous_finish, image_url, source_label, source_url, last_verified) values ('janakpur-bolts', 'Janakpur Bolts', 'Janakpur', 'JB', 'Janakpur', 'Madhesh', '#ff69b4', '#101827', 'Janakpur Bolts represent the historic Mithila region in striking pink and gold. Chanderpaul guides a squad stacked with world stars including Moeen Ali, James Neesham, and Iftikhar Ahmed.', 'Harmeet Singh', 'Shivnarine Chanderpaul', '8th (2025)', null, '2026 NPL squads - Wikipedia (cites auction/retention reports)', 'https://en.wikipedia.org/wiki/2026_Nepal_Premier_League', '2026-10-22') on conflict (id) do nothing;
insert into public.teams (id, name, short_name, abbreviation, city, province, primary_color, accent_color, description, captain, head_coach, previous_finish, image_url, source_label, source_url, last_verified) values ('karnali-yaks', 'Karnali Yaks', 'Karnali', 'KY', 'Surkhet', 'Karnali', '#2635cc', '#f5f7fb', 'The Yaks bring the grit and spirit of Nepal’s mountain province to the NPL. Sompal Kami captains a hard-working group featuring Scotland star Mark Watt, Pakistan all-rounder Hussain Talat, and Gulshan Jha.', 'Sompal Kami', 'Gyanendra Malla', '6th (2025)', null, '2026 NPL squads - Wikipedia (cites auction/retention reports)', 'https://en.wikipedia.org/wiki/2026_Nepal_Premier_League', '2026-10-22') on conflict (id) do nothing;
insert into public.teams (id, name, short_name, abbreviation, city, province, primary_color, accent_color, description, captain, head_coach, previous_finish, image_url, source_label, source_url, last_verified) values ('kathmandu-gurkhas', 'Kathmandu Gorkhas', 'Kathmandu', 'KG', 'Kathmandu', 'Bagmati', '#40e0d0', '#0b1220', 'The capital’s marquee franchise, led by talisman Karan KC. Boosted by global megastar David Warner, Australian all-rounder Will Bosisto, and India wicketkeeper K. S. Bharat playing in Nepal’s largest cricket market.', 'Karan KC', 'Monty Desai', '4th (2025)', null, '2026 NPL squads - Wikipedia (cites auction/retention reports)', 'https://en.wikipedia.org/wiki/2026_Nepal_Premier_League', '2026-10-22') on conflict (id) do nothing;
insert into public.teams (id, name, short_name, abbreviation, city, province, primary_color, accent_color, description, captain, head_coach, previous_finish, image_url, source_label, source_url, last_verified) values ('lumbini-lions', 'Lumbini Lions', 'Lumbini', 'LL', 'Butwal', 'Lumbini', '#e63946', '#f5c542', 'Defending champions. Rohit Paudel’s Lions hoisted the 2025 trophy and return in full force with Australia big-hitter D’Arcy Short, Sri Lanka keeper Niroshan Dickwella, and Namibia pacer Ruben Trumpelmann.', 'Rohit Paudel', 'Tinu Yohannan', 'Champions (2025)', null, '2026 NPL squads - Wikipedia (cites auction/retention reports)', 'https://en.wikipedia.org/wiki/2026_Nepal_Premier_League', '2026-10-22') on conflict (id) do nothing;
insert into public.teams (id, name, short_name, abbreviation, city, province, primary_color, accent_color, description, captain, head_coach, previous_finish, image_url, source_label, source_url, last_verified) values ('pokhara-avengers', 'Pokhara Avengers', 'Pokhara', 'PA', 'Pokhara', 'Gandaki', '#b5173f', '#f5c542', 'The Avengers are the lake city’s team, captained by explosive opener Kushal Bhurtel. Strengthened for Season 3 by world #1 all-rounder Shakib Al Hasan and Sri Lanka international Chamika Karunaratne.', 'Kushal Bhurtel', 'Ajantha Mendis', '5th (2025)', null, '2026 NPL squads - Wikipedia (cites auction/retention reports)', 'https://en.wikipedia.org/wiki/2026_Nepal_Premier_League', '2026-10-22') on conflict (id) do nothing;
insert into public.teams (id, name, short_name, abbreviation, city, province, primary_color, accent_color, description, captain, head_coach, previous_finish, image_url, source_label, source_url, last_verified) values ('sudurpaschim-royals', 'Sudurpaschim Royals', 'Sudurpaschim', 'SR', 'Dhangadhi', 'Sudurpaschim', '#ffd23f', '#0b1220', 'Runners-up in 2025, the Royals are captained by Dipendra Singh Airee (the fastest T20I half-century world record holder) and guided by Misbah-ul-Haq, featuring Pakistan’s Haider Ali and New Zealand’s Scott Kuggeleijn.', 'Dipendra Singh Airee', 'Misbah-ul-Haq', 'Runners-up (2025)', null, '2026 NPL squads - Wikipedia (cites auction/retention reports)', 'https://en.wikipedia.org/wiki/2026_Nepal_Premier_League', '2026-10-22') on conflict (id) do nothing;
